const normalizeEstimateCostDetails = (value) => {
  let details = value;
  if (typeof details === "string") {
    try {
      details = JSON.parse(details);
    } catch (e) {
      return [];
    }
  }
  if (!Array.isArray(details)) return [];
  return details
    .map((item) => {
      if (typeof item === "string") return { description: item };
      if (item && typeof item === "object") {
        return { description: item.description || "" };
      }
      return null;
    })
    .filter(Boolean);
};
const calculateTotalCost = (formData, pdfType) => {
  if (!formData) return "";
  let fieldsToSum = [];
  if (pdfType === "Foundation") {
    fieldsToSum = [
      formData.treatment_cost,
      formData.evaluation_cost,
      formData.surgery_cost,
      formData.accommodation_cost,
      formData.air_ticket_cost,
      formData.other_additional_costs,
      formData.medical_escort_cost
    ];
  } else {
    fieldsToSum = [
      formData.treatment_cost,
      formData.evaluation_cost,
      formData.sim_card_cost,
      formData.accommodation_cost,
      formData.guesthouse_cost,
      formData.air_ticket_cost,
      formData.medif_cost,
      formData.medical_cost,
      formData.physiotherapy_cost,
      formData.medical_escort_cost,
      formData.transport_cost,
      formData.other_additional_costs,
      formData.surgery_cost,
    ];
  }

  let sum = 0;
  let currency = "";

  fieldsToSum.forEach((field) => {
    if (!field) return;
    const str = String(field).trim();
    if (!currency) {
      if (str.toUpperCase().includes("USD")) {
        currency = "USD";
      } else if (str.toUpperCase().includes("MUR")) {
        currency = "MUR";
      } else if (str.includes("$")) {
        currency = "$";
      }
    }

    const clean = str.replace(/,/g, '');
    const match = clean.match(/(\d+(?:\.\d+)?)/);
    if (match) {
      sum += parseFloat(match[1]);
    }
  });

  if (sum === 0) return "";

  const formattedSum = sum.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 });

  if (currency === "USD") {
    return `${formattedSum} USD`;
  } else if (currency === "MUR") {
    return `MUR ${formattedSum} approx.`;
  } else if (currency === "$") {
    return `$${formattedSum}`;
  } else {
    return pdfType === "Foundation" ? `MUR ${formattedSum}` : `${formattedSum} USD`;
  }
};
