const roundTwoDecimals = (val) => Math.round(((Number(val) || 0) + Number.EPSILON) * 100) / 100;
const getCategoryPaymentTotals = (payments = [], defaultPaid = 0, totalAmount = 0) => {
  if (!Array.isArray(payments) || payments.length === 0) {
    const paid = roundTwoDecimals(defaultPaid);
    const total = Number(totalAmount) || 0;
    return {
      approvedPaid: paid,
      pendingAmount: 0,
      dueAmount: roundTwoDecimals(Math.max(0, total - paid)),
    };
  }
  let approved = 0;
  let pending = 0;
  payments.forEach((p) => {
    const amt = Number(p?.paid_amount ?? p?.amount ?? p?.payment ?? 0) || 0;
    const st = getPaymentStatus(p);
    if (st === "Approved") {
      approved += amt;
    } else if (st === "Pending") {
      pending += amt;
    }
  });
  const total = Number(totalAmount) || 0;
  return {
    approvedPaid: roundTwoDecimals(approved),
    pendingAmount: roundTwoDecimals(pending),
    dueAmount: roundTwoDecimals(Math.max(0, total - approved)),
  };
};
const getPriceDisplayValue = (price) => (price === 0 || price ? price : "-");
const getMoneyDisplayValue = (amount) => {
  const value = getPriceDisplayValue(amount);
  return value === "-" ? "-" : `$${value}`;
};
const getDiscountPercentageDisplay = (discount) => {
  if (discount === 0 || discount) return `${discount}%`;
  return "-";
};
const getFinalChargeDisplay = (item, finalKey, baseKey) => {
  if (item?.[finalKey] === 0 || item?.[finalKey]) {
    return getMoneyDisplayValue(item[finalKey]);
  }
  return getMoneyDisplayValue(item?.[baseKey]);
};
const getDiscountedChargeDisplay = (item, baseKey, finalKey) => {
  const finalValue = item?.[finalKey];
  const baseValue = item?.[baseKey];
  const discount = item?.discount_percentage;
  if (finalValue === 0 || finalValue) {
    if (discount === 0 || discount) {
      return `$${finalValue} (${discount}% off from $${baseValue})`;
    }
    return `$${finalValue}`;
  }
  const baseDisplay = getPriceDisplayValue(baseValue);
  return baseDisplay === "-" ? "-" : `$${baseDisplay}`;
};
const calculateFinalFromDiscount = (baseAmount, discountPercentage) => {
  const base = Number(baseAmount);
  const discount = Number(discountPercentage);
  if (!isValidPaidAmount(base) || discountPercentage === "" || discountPercentage == null) {
    return "";
  }
  const final = base - (base * discount) / 100;
  return String(Math.round(final * 100) / 100);
};
const calculateDiscountFromFinal = (baseAmount, finalAmount) => {
  const base = Number(baseAmount);
  const final = Number(finalAmount);
  if (!isValidPaidAmount(base) || !isValidPaidAmount(finalAmount) || base === 0) {
    return "";
  }
  const discount = ((base - final) / base) * 100;
  return String(Math.round(discount * 100) / 100);
};
const updateDiscountedFields = (
  currentValue,
  name,
  value,
  baseField,
  finalField,
) => {
  const next = {
    ...(currentValue && typeof currentValue === "object" ? currentValue : {}),
    [name]: value,
  };

  if (name === baseField) {
    if (next.discount_percentage !== "") {
      next[finalField] = calculateFinalFromDiscount(
        value,
        next.discount_percentage,
      );
    } else if (next[finalField] !== "") {
      next.discount_percentage = calculateDiscountFromFinal(
        value,
        next[finalField],
      );
    }
  } else if (name === "discount_percentage" && value !== "") {
    next[finalField] = calculateFinalFromDiscount(next[baseField], value);
  } else if (name === finalField && value !== "") {
    next.discount_percentage = calculateDiscountFromFinal(
      next[baseField],
      value,
    );
  }

  return next;
};
