    const notes = (entry.notes || entry.note || "").trim().toLowerCase();

    // Check if entry represents a VIL upload / pending status
    const isVilUploadStatus = /vil\s*(upload|uploaded|pending)/i.test(status);
    if (!isVilUploadStatus) return false;

