    const discountError = getDiscountValidationError(
      data.paymentAmount,
      data.discount_percentage,
      data.final_amount,
    );
    if (discountError) {
      return Swal.fire("Error", discountError, "error");
    }
    if (!data.paymentDate) {
      return Swal.fire("Error", "Payment Date is required", "error");
    }
    if (!data.notes?.trim()) {
      return Swal.fire("Error", "Notes is required", "error");
    }
