                                                      background: "#ffffff",
                                                      border: "1px solid #e2e8f0",
                                                      boxShadow: "0 1px 3px rgba(0,0,0,0.04)",
                                                      display: "flex",
                                                      alignItems: "center",
                                                      justifyContent: "space-between",
                                                      flexWrap: "wrap",
                                                      gap: "12px",
