                                                                <span className="status-badge vil-pending m-0" style={{ fontSize: "12px", padding: "4px 10px", fontWeight: "500" }}>
                                                                  <i className="fa-solid fa-clock me-1"></i>
                                                                  {formatVilStatusWithStinker(
                                                                    "VIL Pending Review",
                                                                    item,
                                                                    info,
                                                                  )}
                                                                </span>
